//! Reference outputs from the public Rust builder for Python integration tests.
//! Generated by scripts/generate_builder_reference.py; not a second engine.
use textforge::{
    api::{
        TextForgeBlockMethods, TextForgeBuilderMethods, TextForgeConditionalMethods, get_var,
        processor::{TextForgeProcessor, TextForgeProcessorMethods},
    },
    parser::{
        params::TextForgeParamTypes,
        resolve_var::{TokenWrapper, ValType},
    },
    utils::errors::TextForgeError,
};

fn record(name: &str, result: Result<String, TextForgeError>) {
    match result {
        Ok(text) => {
            let encoded: String = text
                .as_bytes()
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect();
            println!("{name}\tok\t{encoded}");
        }
        Err(error) => println!("{name}\terror\t{}", error.error_code.get_error_code()),
    }
}

